content.text:
/// The scripted conversation config for [MockLlmServer]: a YAML or JSON
/// document mapping user messages to queues of responses.
///
/// Document shape (YAML; JSON is a YAML subset, so the same parser takes
/// both):
///
/// ```yaml
/// model: mock-model            # optional, reported by GET /models
/// responses:                   # optional fallback queue, no scenario match
///   - text: "done"
/// scenarios:
///   - match: "list the files"  # substring of the LAST user message
///     responses:               # popped in order, one per request
///       - toolCall:
///           name: bash
///           arguments: '{"command": "ls"}'
///       - toolResultEcho: true
///       - text: "listed"
///       - error: {status: 503, message: "mock outage"}
///   - match: "Existing tags:"  # background noise: call count is
///     sticky: true             # schedule-dependent — re-serve the LAST
///     responses:               # response forever instead of exhausting
///       - text: ""
/// ```
///
/// One response entry per map, keyed by exactly one of:
/// - `text` — assistant text (streamed, `finish_reason: stop`).
/// - `toolCall` — one function call (`name`, `arguments` string or any
///   JSON-encodable value; `finish_reason: tool_calls`).
/// - `toolResultEcho` — echoes the last `role: "tool"` message content
///   back as assistant text (proves a tool result actually flowed).
/// - `error` — HTTP error simulation: `{status: <int>, message: <str>}`
///   (defaults 500 / `mock llm error`), surfaced by adapters as an error
///   turn.
///
/// Scenario key `sticky: true` — once the queue runs dry, every further
/// matching request re-serves the LAST response instead of answering HTTP
/// 500 `script exhausted`. For background-noise scenarios whose call count
/// is schedule-dependent (memory auto-tag generation, title/summary
/// calls); the scripted conversation itself stays strict so a missing
/// response still fails loudly.
///
/// Routing per `/chat/completions` request: the FIRST scenario whose
/// `match` is a substring of the last user message pops the front of its
/// queue; no match pops the top-level `responses` queue; an empty queue
/// (or no fallback) answers HTTP 500 `script exhausted` — unless the
/// matched scenario is sticky, which keeps serving its last response.
library;

import 'dart:convert';
import 'dart:io';

import 'package:yaml/yaml.dart';

/// One scripted response. Subtypes: [MockText], [MockToolCall],
/// [MockToolResultEcho], [MockError].
sealed class MockResponse {
  const MockResponse();
}

/// A plain assistant text message.
final class MockText extends MockResponse {
  const MockText(this.text);

  final String text;
}

/// One streamed function call. [argumentsJson] is the raw JSON argument
/// string sent in the `tool_calls` delta.
final class MockToolCall extends MockResponse {
  const MockToolCall(this.name, this.argumentsJson);

  final String name;
  final String argumentsJson;
}

/// Echoes the last `role: "tool"` message content of the request back as
/// assistant text — the marker a real model quotes the tool result with.
final class MockToolResultEcho extends MockResponse {
  const MockToolResultEcho();
}

/// An error simulation: HTTP [status] with a JSON error [message] body.
final class MockError extends MockResponse {
  const MockError({this.status = 500, this.message = 'mock llm error'});

  final int status;
  final String message;
}

/// One scenario: when [match] occurs in the last user message, the server
/// pops [responses] in order.
///
/// [sticky] turns the scenario into a wildcard once its queue runs dry: the
/// LAST response is re-served for every further matching request instead of
/// exhausting into the HTTP 500. Use it for background-noise traffic whose
/// call count is schedule-dependent (memory auto-tag generation, session
/// title/summary calls) — never for the scripted conversation itself, whose
/// exhaustion must keep failing loudly.
final class MockScenario {
  const MockScenario({
    required this.match,
    required this.responses,
    this.sticky = false,
  });

  /// Substring tested against the last `role: "user"` message content.
  final String match;

  final List<MockResponse> responses;

  /// When true, a dry queue keeps answering with its last response forever.
  final bool sticky;
}

/// A parsed mock script: the reported [model], per-message [scenarios],
/// and the fallback [responses] queue.
final class MockLlmScript {
  const MockLlmScript({
    this.model = 'mock-model',
    this.scenarios = const [],
    this.responses = const [],
  });

  /// Model id reported by `GET /models` and in SSE chunk metadata.
  final String model;

  /// Matched in order; first hit wins.
  final List<MockScenario> scenarios;

  /// Queue popped when no scenario matches.
  final List<MockResponse> responses;

  /// Parses a YAML (or JSON — a YAML subset) script document.
  ///
  /// Throws [MockLlmConfigException] with the offending key path on any
  /// structural problem: strict on purpose — a typo in a test fixture
  /// must fail at startup, not silently fall through to the fallback.
  static MockLlmScript parse(String source) {
    final Object? doc;
    try {
      doc = loadYaml(source);
    } on YamlException catch (error) {
      throw MockLlmConfigException('invalid YAML/JSON: $error');
    }
    return _parseDoc(doc, '');
  }

  /// Parses the script document at [path].
  static MockLlmScript parseFile(String path) =>
      parse(File(path).readAsStringSync());
}

/// A structurally invalid mock script document.
final class MockLlmConfigException implements Exception {
  MockLlmConfigException(this.message);

  final String message;

  @override
  String toString() => 'MockLlmConfigException: $message';
}

MockLlmScript _parseDoc(Object? doc, String path) {
  if (doc is! YamlMap) {
    throw MockLlmConfigException(
      '${_at(path)}expected a mapping at the document root',
    );
  }
  final model = _optString(doc, 'model', path);
  final scenarios = <MockScenario>[];
  final responses = <MockResponse>[];
  for (final key in doc.keys) {
    final keyPath = _join(path, '$key');
    switch (key) {
      case 'model':
        break; // already read
      case 'scenarios':
        final raw = doc[key];
        if (raw is! YamlList) {
          throw MockLlmConfigException('$keyPath must be a list');
        }
        for (var i = 0; i < raw.length; i++) {
          scenarios.add(_parseScenario(raw[i], '$keyPath[$i]'));
        }
      case 'responses':
        responses.addAll(_parseResponses(doc[key], keyPath));
      default:
        throw MockLlmConfigException('${_at(keyPath)}unknown key');
    }
  }
  return MockLlmScript(
    model: model ?? 'mock-model',
    scenarios: List.unmodifiable(scenarios),
    responses: List.unmodifiable(responses),
  );
}

MockScenario _parseScenario(Object? node, String path) {
  if (node is! YamlMap) {
    throw MockLlmConfigException('${_at(path)}expected a mapping');
  }
  final match = _reqString(node, 'match', path);
  final responses = _parseResponses(
    node['responses'],
    _join(path, 'responses'),
  );
  final sticky = _optBool(node, 'sticky', path) ?? false;
  for (final key in node.keys) {
    if (key != 'match' && key != 'responses' && key != 'sticky') {
      throw MockLlmConfigException('${_at(_join(path, '$key'))}unknown key');
    }
  }
  return MockScenario(match: match, responses: responses, sticky: sticky);
}

List<MockResponse> _parseResponses(Object? node, String path) {
  if (node == null) return const [];
  if (node is! YamlList) {
    throw MockLlmConfigException('${_at(path)}must be a list');
  }
  return [
    for (var i = 0; i < node.length; i++) _parseResponse(node[i], '$path[$i]'),
  ];
}

MockResponse _parseResponse(Object? node, String path) {
  if (node is! YamlMap) {
    throw MockLlmConfigException(
      '${_at(path)}expected a mapping with one of text/toolCall/'
      'toolResultEcho/error',
    );
  }
  if (node.length != 1) {
    throw MockLlmConfigException(
      '${_at(path)}expected exactly one of text/toolCall/toolResultEcho/'
      'error, got [${node.keys.join(', ')}]',
    );
  }
  final key = '${node.keys.first}';
  final value = node.values.first;
  switch (key) {
    case 'text':
      if (value is! String) {
        throw MockLlmConfigException('${_at(path)}text must be a string');
      }
      return MockText(value);
    case 'toolCall':
      if (value is! YamlMap) {
        throw MockLlmConfigException(
          '${_at(path)}toolCall must be a mapping with name/arguments',
        );
      }
      final name = _reqString(value, 'name', '$path.toolCall');
      final arguments = value['arguments'];
      // A string rides verbatim (the wire format); any other value is
      // JSON-encoded so fixture authors can write structured arguments.
      final argumentsJson = arguments is String
          ? arguments
          : jsonEncode(arguments ?? {});
      return MockToolCall(name, argumentsJson);
    case 'toolResultEcho':
      if (value is! bool) {
        throw MockLlmConfigException(
          '${_at(path)}toolResultEcho must be a boolean',
        );
      }
      return const MockToolResultEcho();
    case 'error':
      if (value is! YamlMap) {
        throw MockLlmConfigException(
          '${_at(path)}error must be a mapping with status/message',
        );
      }
      final status = _optInt(value, 'status', '$path.error') ?? 500;
      final message =
          _optString(value, 'message', '$path.error') ?? 'mock llm error';
      for (final errorKey in value.keys) {
        if (errorKey != 'status' && errorKey != 'message') {
          throw MockLlmConfigException(
            '${_at('$path.error.$errorKey')}unknown key',
          );
        }
      }
      return MockError(status: status, message: message);
    default:
      throw MockLlmConfigException(
        '${_at(path)}unknown response kind "$key" (expected text/toolCall/'
        'toolResultEcho/error)',
      );
  }
}

String? _optString(YamlMap map, String key, String path) {
  final value = map[key];
  if (value == null) return null;
  if (value is! String) {
    throw MockLlmConfigException('${_at(_join(path, key))}must be a string');
  }
  return value;
}

String _reqString(YamlMap map, String key, String path) {
  return _optString(map, key, path) ??
      (throw MockLlmConfigException('${_at(_join(path, key))}is required'));
}

int? _optInt(YamlMap map, String key, String path) {
  final value = map[key];
  if (value == null) return null;
  if (value is! int) {
    throw MockLlmConfigException('${_at(_join(path, key))}must be an integer');
  }
  return value;
}

bool? _optBool(YamlMap map, String key, String path) {
  final value = map[key];
  if (value == null) return null;
  if (value is! bool) {
    throw MockLlmConfigException('${_at(_join(path, key))}must be a boolean');
  }
  return value;
}

String _join(String path, String key) => path.isEmpty ? key : '$path.$key';

String _at(String path) => path.isEmpty ? '' : '$path: ';

/// Scripted OpenAI-compatible mock LLM server for integration tests.
///
/// Binds a loopback HTTP server on an ephemeral port and answers
/// `POST <baseUrl>/chat/completions` (the exact path
/// `streamOpenAICompletions` builds: `{model.baseUrl}/chat/completions`)
/// with OpenAI-style SSE chunks carrying the scripted responses:
///
/// - [MockToolCall]: one streamed `tool_calls` delta plus
///   `finish_reason: "tool_calls"`.
/// - [MockText]: one `content` delta plus `finish_reason: "stop"`.
/// - [MockToolResultEcho]: a `content` response echoing back the text of
///   the last `role: "tool"` message in the request (what a real model
///   would quote); proves the tool result actually flowed through the
///   sandbox.
/// - [MockError]: HTTP error simulation — the requested status with a
///   JSON error body, surfaced by adapters as an error turn.
///
/// The script comes either from a config document
/// (`MockLlmScript.parse`) with per-user-message scenarios and response
/// queues, or programmatically via [enqueueToolCall]/[enqueueText]/
/// [enqueueToolResultEcho] (a plain FIFO queue). A request arriving with
/// nothing scripted gets an HTTP 500 JSON error, which the adapter
/// surfaces as an error turn (headless exit code 1). `GET .../models`
/// answers a minimal model list; everything else is 404.
///
/// Deterministic: no real LLM, no external network.
library;

import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'mock_llm_script.dart';

/// One scenario's live routing state: the parsed [match]/[sticky] flags,
/// the deep-copied [queue], and the LAST served response (a sticky
/// scenario re-serves it once the queue runs dry).
final class _ScenarioQueue {
  _ScenarioQueue(this.match, this.sticky, List<MockResponse> responses)
    : queue = List.of(responses);

  final String match;
  final bool sticky;
  final List<MockResponse> queue;
  MockResponse? last;
}

final class MockLlmServer {
  MockLlmServer._(this._server, this.baseUrl)
    : _model = null,
      _scenarios = const [],
      _fallback = [];

  MockLlmServer._scripted(this._server, this.baseUrl, MockLlmScript script)
    : _model = script.model,
      // Deep-copy the queues: one server instance owns its pops, and the
      // same parsed script stays reusable for a second start().
      _scenarios = [
        for (final scenario in script.scenarios)
          _ScenarioQueue(scenario.match, scenario.sticky, scenario.responses),
      ],
      _fallback = List.of(script.responses);

  final HttpServer _server;
  final String? _model;
  final List<_ScenarioQueue> _scenarios;
  final List<MockResponse> _fallback;
  var _chatCalls = 0;
  final _chatBodies = <String>[];

  /// The base URL to pass as the CLI's `--base-url` (trailing `/v1`, so the
  /// adapter's `{baseUrl}/chat/completions` lands on `/v1/chat/completions`).
  final String baseUrl;

  /// The bound loopback port (derived from [baseUrl]).
  int get port => Uri.parse(baseUrl).port;

  /// Starts the server on a loopback ephemeral port with an empty script
  /// (script it programmatically via the `enqueue*` methods), or from a
  /// parsed [script] with scenarios and a fallback queue.
  static Future<MockLlmServer> start({MockLlmScript? script}) async {
    final server = await HttpServer.bind(InternetAddress.loopbackIPv4, 0);
    final mock = script == null
        ? MockLlmServer._(server, 'http://127.0.0.1:${server.port}/v1')
        : MockLlmServer._scripted(
            server,
            'http://127.0.0.1:${server.port}/v1',
            script,
          );
    server.listen(mock._handle);
    return mock;
  }

  /// How many `/chat/completions` requests were served so far.
  int get chatCalls => _chatCalls;

  /// Raw bodies of the served `/chat/completions` requests, in call order
  /// — lets tests assert on the exact wire payload (e.g. the `tools`
  /// array) without changing any scripted behavior.
  List<String> get chatBodies => List.unmodifiable(_chatBodies);

  /// Scripts the next programmatic response as a streamed tool call.
  void enqueueToolCall(String name, String argumentsJson) {
    _fallback.add(MockToolCall(name, argumentsJson));
  }

  /// Scripts the next programmatic response as a plain assistant text
  /// message.
  void enqueueText(String text) {
    _fallback.add(MockText(text));
  }

  /// Scripts the next programmatic response as assistant text echoing the
  /// last tool result content from the request.
  void enqueueToolResultEcho() {
    _fallback.add(const MockToolResultEcho());
  }

  /// Closes the server and every open connection.
  Future<void> stop() => _server.close(force: true);

  Future<void> _handle(HttpRequest request) async {
    final path = request.uri.path;
    if (request.method == 'POST' && path.endsWith('/chat/completions')) {
      await _handleChat(request);
      return;
    }
    if (request.method == 'GET' && path.endsWith('/models')) {
      await _respondJson(request, 200, {
        'object': 'list',
        'data': [
          {'id': _model ?? 'mock-model', 'object': 'model'},
        ],
      });
      return;
    }
    await _respondJson(request, 404, {
      'error': {'message': 'mock: $path'},
    });
  }

  Future<void> _handleChat(HttpRequest request) async {
    final body = await utf8.decoder.bind(request).join();
    _chatCalls++;
    _chatBodies.add(body);
    final entry = _nextEntry(body);
    if (entry == null) {
      await _respondJson(request, 500, {
        'error': {'message': 'mock: script exhausted after $_chatCalls calls'},
      });
      return;
    }
    switch (entry) {
      case MockError(:final status, :final message):
        await _respondJson(request, status, {
          'error': {'message': message},
        });
      case MockToolCall(:final name, :final argumentsJson):
        await _respondSse(request, [
          _chunk(_toolCallDelta(name, argumentsJson), null),
          _chunk(const {}, 'tool_calls'),
        ]);
      case MockToolResultEcho():
        await _respondSse(request, [
          _chunk({'content': _lastToolResultText(body)}, null),
          _chunk(const {}, 'stop'),
        ]);
      case MockText(:final text):
        await _respondSse(request, [
          _chunk({'content': text}, null),
          _chunk(const {}, 'stop'),
        ]);
    }
  }

  /// Pops the next scripted response: the first scenario whose [match] is
  /// a substring of the last user message, else the fallback queue. A
  /// matched-but-empty scenario stays exhausted (500) — it owns the
  /// conversation once matched — unless it is sticky, which keeps serving
  /// its LAST response forever (background-noise tolerance, gh-1171).
  MockResponse? _nextEntry(String body) {
    final user = _lastUserText(body);
    for (final scenario in _scenarios) {
      if (scenario.match.isEmpty || user.contains(scenario.match)) {
        if (scenario.queue.isNotEmpty) {
          final next = scenario.queue.removeAt(0);
          scenario.last = next;
          return next;
        }
        return scenario.sticky ? scenario.last : null;
      }
    }
    return _fallback.isEmpty ? null : _fallback.removeAt(0);
  }

  /// The text of the last `role: "tool"` message in the request body, or a
  /// marker when the request carried none.
  String _lastToolResultText(String body) {
    final decoded = _decode(body);
    final messages = _messagesOf(decoded);
    for (final message in messages.reversed) {
      if (message is Map && message['role'] == 'tool') {
        return _contentText(message['content']);
      }
    }
    return 'mock: request had no tool result';
  }

  /// The content of the last `role: "user"` message in the request body,
  /// or '' when the request carried none.
  String _lastUserText(String body) {
    final decoded = _decode(body);
    final messages = _messagesOf(decoded);
    for (final message in messages.reversed) {
      if (message is Map && message['role'] == 'user') {
        return _contentText(message['content']);
      }
    }
    return '';
  }

  static Object? _decode(String body) {
    try {
      return jsonDecode(body);
    } on FormatException {
      return null;
    }
  }

  static List<Object?> _messagesOf(Object? decoded) {
    if (decoded is! Map) return const [];
    final messages = decoded['messages'];
    return messages is List ? messages : const [];
  }

  /// String content rides as-is; OpenAI array content contributes its
  /// `text` parts joined by newlines.
  static String _contentText(Object? content) {
    if (content is String) return content;
    if (content is List) {
      return [
        for (final part in content)
          if (part is Map && part['text'] is String) part['text'] as String,
      ].join('\n');
    }
    return jsonEncode(content);
  }

  Map<String, dynamic> _toolCallDelta(String name, String argumentsJson) {
    return {
      'tool_calls': [
        {
          'index': 0,
          'id': 'call_mock_$_chatCalls',
          'type': 'function',
          'function': {'name': name, 'arguments': argumentsJson},
        },
      ],
    };
  }

  Map<String, dynamic> _chunk(Map<String, dynamic> delta, String? finish) {
    return {
      'id': 'chatcmpl-mock-$_chatCalls',
      'object': 'chat.completion.chunk',
      'model': _model ?? 'mock-model',
      'choices': [
        {'index': 0, 'delta': delta, 'finish_reason': finish},
      ],
    };
  }

  Future<void> _respondSse(
    HttpRequest request,
    List<Map<String, dynamic>> chunks,
  ) async {
    request.response.headers.contentType = ContentType('text', 'event-stream');
    final buffer = StringBuffer();
    for (final chunk in chunks) {
      buffer.write('data: ${jsonEncode(chunk)}\n\n');
    }
    buffer.write('data: [DONE]\n\n');
    request.response.write(buffer.toString());
    await request.response.close();
  }

  Future<void> _respondJson(
    HttpRequest request,
    int status,
    Object? body,
  ) async {
    request.response.statusCode = status;
    request.response.headers.contentType = ContentType.json;
    request.response.write(jsonEncode(body));
    await request.response.close();
  }
}

