      final script = MockLlmScript.parse('''
scenarios:
  - match: "Use the task tool"
    responses:
      - toolCall:
          name: task
          arguments: >-
            {"context":"Prove the task loop","tasks":[{"name":"explorer1",
            "agent":"explore","task":"List the files in the current
            directory.","background":false}]}
