scenarios:
  - match: "Use the memory_add tool"
    responses:
      - toolCall:
          name: memory_add
          arguments: '{"text": "The project uses Dart 3.12"}'
      - toolCall:
          name: memory_search
          arguments: '{"query": "Dart"}'
      - text: "memory round-trip complete"
  - match: "Existing tags:"
    sticky: true
    responses:
      - text: ""
''');
